"""Shared bpy code-generation helpers.

Every generated .bpy file is SELF-CONTAINED: the helpers below are
printed into it, so a file runs with just:
    blender --background --python <file>.bpy -- --out <dir>
No addons, no external assets — all materials are procedural PBR,
textures are generated nodes (noise/voronoi/musgrave/wave), and UVs
are computed with Smart UV Project. Physics (rigid body, cloth,
hair particles, collision) is wired per spec.
"""

HEADER = r'''
# ═══════════════════════════════════════════════════════════════
#  Auto-generated by blender_pipeline — {title}
#  Run:  blender --background --python {filename} -- --out <dir>
#  Self-contained: procedural PBR materials, smart UVs, physics.
# ═══════════════════════════════════════════════════════════════
import bpy, bmesh, math, os, sys, random
from mathutils import Vector, Euler

random.seed({seed})
argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
OUT = argv[argv.index("--out") + 1] if "--out" in argv else os.path.dirname(bpy.data.filepath) or "."

# ── scene reset ──
for ob in list(bpy.data.objects):
    bpy.data.objects.remove(ob, do_unlink=True)
for block in (bpy.data.meshes, bpy.data.materials, bpy.data.lights, bpy.data.cameras, bpy.data.images):
    for b in list(block):
        if b.users == 0:
            block.remove(b)

SCN = bpy.context.scene
SCN.unit_settings.system = 'METRIC'

def col(name):
    c = bpy.data.collections.new(name)
    SCN.collection.children.link(c)
    return c

def link(ob, collection=None):
    (collection or SCN.collection).objects.link(ob)
    return ob

def smooth(obj, levels=2, render=3, shade=True):
    m = obj.modifiers.new("Subsurf", 'SUBSURF')
    m.levels = levels
    m.render_levels = render
    if shade:
        for p in obj.data.polygons:
            p.use_smooth = True
    return m

def bevel(obj, width=0.004, segments=3):
    m = obj.modifiers.new("Bevel", 'BEVEL')
    m.width = width
    m.segments = segments
    m.limit_method = 'ANGLE'
    m.angle_limit = math.radians(48)
    return m

def solidify(obj, thickness=0.01, offset=-1.0):
    m = obj.modifiers.new("Solidify", 'SOLIDIFY')
    m.thickness = thickness
    m.offset = offset
    return m

def displace_noise(obj, strength=0.05, scale=3.0, tex_name=None):
    tex = bpy.data.textures.new(tex_name or "NoiseTex", type='CLOUDS')
    tex.noise_scale = scale
    m = obj.modifiers.new("Displace", 'DISPLACE')
    m.texture = tex
    m.strength = strength
    m.mid_level = 0.5
    return m

def smart_uv(obj, angle=66.0):
    bpy.context.view_layer.objects.active = obj
    bpy.ops.object.mode_set(mode='EDIT')
    bpy.ops.mesh.select_all(action='SELECT')
    bpy.ops.uv.smart_project(angle_limit=math.radians(angle), island_margin=0.02)
    bpy.ops.object.mode_set(mode='OBJECT')

def mat(name, base=(0.5, 0.5, 0.5, 1.0), rough=0.6, metal=0.0,
        sss=0.0, sss_color=None, emit=0.0, alpha=1.0, ior=1.45):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    nt = m.node_tree
    bsdf = nt.nodes["Principled BSDF"]
    bsdf.inputs["Base Color"].default_value = base
    bsdf.inputs["Roughness"].default_value = rough
    bsdf.inputs["Metallic"].default_value = metal
    if "IOR" in bsdf.inputs:
        bsdf.inputs["IOR"].default_value = ior
    if sss > 0:
        try:
            bsdf.inputs["Subsurface Weight"].default_value = sss
            if sss_color:
                bsdf.inputs["Subsurface Radius"].default_value = sss_color
        except KeyError:
            # Blender < 4.0 naming
            bsdf.inputs["Subsurface"].default_value = sss
    if emit > 0:
        try:
            bsdf.inputs["Emission Color"].default_value = base
            bsdf.inputs["Emission Strength"].default_value = emit
        except KeyError:
            bsdf.inputs["Emission"].default_value = base
            bsdf.inputs["Emission Strength"].default_value = emit
    if alpha < 1.0:
        bsdf.inputs["Alpha"].default_value = alpha
        m.blend_method = 'BLEND'
    return m

def noise_bump(m, scale=6.0, strength=0.25, detail=6.0, roughness=True):
    """Procedural micro-texture: noise -> bump + roughness variance."""
    nt = m.node_tree
    bsdf = nt.nodes["Principled BSDF"]
    noise = nt.nodes.new("ShaderNodeTexNoise")
    noise.inputs["Scale"].default_value = scale
    noise.inputs["Detail"].default_value = detail
    bump = nt.nodes.new("ShaderNodeBump")
    bump.inputs["Strength"].default_value = strength
    nt.links.new(noise.outputs["Fac"], bump.inputs["Height"])
    nt.links.new(bump.outputs["Normal"], bsdf.inputs["Normal"])
    if roughness:
        ramp = nt.nodes.new("ShaderNodeMapRange")
        ramp.inputs["From Min"].default_value = 0.0
        ramp.inputs["From Max"].default_value = 1.0
        ramp.inputs["To Min"].default_value = max(0.05, roughness - 0.15)
        ramp.inputs["To Max"].default_value = min(1.0, roughness + 0.15)
        nt.links.new(noise.outputs["Fac"], ramp.inputs["Value"])
        nt.links.new(ramp.outputs["Result"], bsdf.inputs["Roughness"])
    return noise

def voronoi_grain(m, scale=30.0, strength=0.4):
    """Cell-grain bump (leather, hide, knapped stone)."""
    nt = m.node_tree
    bsdf = nt.nodes["Principled BSDF"]
    vor = nt.nodes.new("ShaderNodeTexVoronoi")
    vor.inputs["Scale"].default_value = scale
    bump = nt.nodes.new("ShaderNodeBump")
    bump.inputs["Strength"].default_value = strength
    nt.links.new(vor.outputs["Distance"], bump.inputs["Height"])
    nt.links.new(bump.outputs["Normal"], bsdf.inputs["Normal"])
    return vor

def wave_grain(m, scale=8.0, distortion=4.0, strength=0.3, color2=None):
    """Wood/fibre grain: wave texture drives both bump and color mix."""
    nt = m.node_tree
    bsdf = nt.nodes["Principled BSDF"]
    wave = nt.nodes.new("ShaderNodeTexWave")
    wave.inputs["Scale"].default_value = scale
    wave.inputs["Distortion"].default_value = distortion
    wave.bands_direction = 'X'
    bump = nt.nodes.new("ShaderNodeBump")
    bump.inputs["Strength"].default_value = strength
    nt.links.new(wave.outputs["Fac"], bump.inputs["Height"])
    nt.links.new(bump.outputs["Normal"], bsdf.inputs["Normal"])
    if color2:
        ramp = nt.nodes.new("ShaderNodeValToRGB")
        ramp.color_ramp.elements[0].color = bsdf.inputs["Base Color"].default_value
        ramp.color_ramp.elements[1].color = (*color2, 1.0)
        nt.links.new(wave.outputs["Fac"], ramp.inputs["Fac"])
        nt.links.new(ramp.outputs["Color"], bsdf.inputs["Base Color"])
    return wave
'''

# Physics source appended after the header (needs SCN defined above)
RIGID_SRC = r'''
def rigid(obj, mass=1.0, bounces=True):
    bpy.context.view_layer.objects.active = obj
    bpy.ops.rigidbody.object_add()
    obj.rigid_body.mass = mass
    obj.rigid_body.restitution = 0.25 if bounces else 0.0
    obj.rigid_body.friction = 0.7
    return obj.rigid_body

def cloth(obj, quality=8, mass=0.4, tension=40):
    bpy.context.view_layer.objects.active = obj
    bpy.ops.object.modifier_add(type='CLOTH')
    c = obj.modifiers["Cloth"].settings
    c.quality = quality
    c.mass = mass
    c.tension_stiffness = tension
    c.compression_stiffness = tension
    return obj.modifiers["Cloth"]

def collision(obj):
    bpy.context.view_layer.objects.active = obj
    bpy.ops.object.modifier_add(type='COLLISION')
    return obj.modifiers["Collision"]

def hair_system(obj, strands=3000, children=6, length=0.1, radius=0.004,
                color=(0.05, 0.04, 0.035), clump=0.3, kink=0.15, name="Hair"):
    """Real strand hair with interpolated children (per-strand economy),
    clumping + kink for the peppercorn coil look."""
    ps = obj.modifiers.new(name, 'PARTICLE_SYSTEM')
    p = ps.particle_system.settings
    p.name = name
    p.count = strands
    p.type = 'HAIR'
    p.hair_length = length
    p.hair_step = 5
    p.child_type = 'INTERPOLATED'
    p.child_percent = children
    p.rendered_child_percent = children * 2
    p.clump_factor = clump
    p.roughness_endpoint = kink
    p.roughness_2 = kink * 0.6
    p.root_radius = radius * 1.6
    p.tip_radius = 0.0
    # hair material
    hm = bpy.data.materials.new(name + "_mat")
    hm.use_nodes = True
    nt = hm.node_tree
    for n in list(nt.nodes):
        nt.nodes.remove(n)
    out = nt.nodes.new("ShaderNodeOutputMaterial")
    hair = nt.nodes.new("ShaderNodeBsdfHair")
    hair.inputs["Melanin"].default_value = color[0] * 8 + 0.4
    nt.links.new(hair.outputs["Hair"], out.inputs["Surface"])
    p.material = len(obj.data.materials)
    obj.data.materials.append(hm)
    return ps

def keyframe_pose(obj, frame, rotation=None, location=None):
    if rotation is not None:
        obj.rotation_euler = rotation
        obj.keyframe_insert(data_path="rotation_euler", frame=frame)
    if location is not None:
        obj.location = location
        obj.keyframe_insert(data_path="location", frame=frame)

def bake_frame_range(start, end):
    SCN.frame_start = start
    SCN.frame_end = end
'''

FOOTER = r'''
# ── export ──
def export(objs):
    os.makedirs(OUT, exist_ok=True)
    name = os.path.splitext(os.path.basename(__file__))[0]
    # select export set
    bpy.ops.object.select_all(action='DESELECT')
    for o in objs:
        if o and o.name in bpy.data.objects:
            o.select_set(True)
    bpy.context.view_layer.objects.active = objs[0]
    glb = os.path.join(OUT, name + ".glb")
    try:
        bpy.ops.export_scene.gltf(filepath=glb, use_selection=True, export_format='GLB')
    except Exception as e:
        print("GLB export skipped:", e)
    blend = os.path.join(OUT, name + ".blend")
    bpy.ops.wm.save_as_mainfile(filepath=blend)
    print("WROTE", glb, "and", blend)

print("=== {title}: build complete ===")
'''


def emit_header(title, filename, seed=42):
    return (
        HEADER.format(title=title, filename=filename, seed=seed)
        + RIGID_SRC
    )
